import { useState } from 'react';

export default function App() {
  const [count, setCount] = useState(0);

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white rounded-lg shadow-lg p-8 w-96">
        <h1 className="text-3xl font-bold text-center mb-8 text-gray-800">
          Contador
        </h1>

        <div className="flex items-center justify-center gap-6 mb-8">
          <button
            onClick={() => setCount(count - 1)}
            className="bg-red-500 hover:bg-red-600 text-white font-bold py-3 px-6 rounded-lg text-xl transition-colors"
          >
            -
          </button>

          <span className="text-5xl font-bold text-gray-800 min-w-20 text-center">
            {count}
          </span>

          <button
            onClick={() => setCount(count + 1)}
            className="bg-green-500 hover:bg-green-600 text-white font-bold py-3 px-6 rounded-lg text-xl transition-colors"
          >
            +
          </button>
        </div>

        <div className="text-center mb-4">
          <p className="text-lg text-gray-700">
            El doble es <span className="font-bold">{count * 2}</span>
          </p>
        </div>

        {count > 5 && (
          <div className="text-center">
            <p className="text-lg font-bold text-orange-500">¡Más de 5!</p>
          </div>
        )}
      </div>
    </div>
  );
}

