model Todo {
  id: ID
  title: String
  done: Bool
}

component TodoItem(todo: Todo, onDelete: Fn) {
  column gap=2 pad=2 {
    row gap=3 align=center {
      input type=checkbox todo.done
      text todo.title muted=todo.done
      button "×" danger small -> onDelete(todo.id)
    }
  }
}

page Todos "/todos" {
  state todos: Todo[] = []
  state draft = ""

  fn add() {
    if draft.trim() == "" { return }
    todos.push({ id: crypto.randomUUID(), title: draft, done: false })
    draft = ""
  }

  fn deleteTodo(id) {
    todos = todos.filter(t => t.id != id)
  }

  computed pending = todos.filter(t => !t.done).length

  column gap=4 pad=4 {
    title "Mis tareas"
    row gap=2 {
      input draft placeholder="¿Qué hay que hacer?" -> add()
      button "Agregar" primary -> add()
    }
    if todos.length == 0 {
      text "No hay tareas" muted
    } else {
      for t in todos {
        TodoItem todo=t onDelete=deleteTodo
      }
      text `${pending} pendientes` muted small
    }
  }
}

