'use client';

import React, { useState } from 'react';
import { Trash2, Plus } from 'lucide-react';

interface Task {
  id: string;
  text: string;
  completed: boolean;
}

const TaskItem: React.FC<{
  task: Task;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}> = ({ task, onToggle, onDelete }) => {
  return (
    <div className="flex items-center gap-3 p-3 bg-white border border-gray-200 rounded-lg hover:shadow-md transition-shadow">
      <input
        type="checkbox"
        checked={task.completed}
        onChange={() => onToggle(task.id)}
        className="w-5 h-5 text-blue-600 rounded cursor-pointer accent-blue-600"
      />
      <span
        className={`flex-1 text-sm ${
          task.completed
            ? 'line-through text-gray-400'
            : 'text-gray-800'
        }`}
      >
        {task.text}
      </span>
      <button
        onClick={() => onDelete(task.id)}
        className="p-1 text-red-500 hover:bg-red-50 rounded transition-colors"
        aria-label="Eliminar tarea"
      >
        <Trash2 size={18} />
      </button>
    </div>
  );
};

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [input, setInput] = useState('');

  const addTask = () => {
    const trimmedText = input.trim();
    if (trimmedText === '') return;

    const newTask: Task = {
      id: Date.now().toString(),
      text: trimmedText,
      completed: false,
    };

    setTasks([...tasks, newTask]);
    setInput('');
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      addTask();
    }
  };

  const toggleTask = (id: string) => {
    setTasks(
      tasks.map((task) =>
        task.id === id ? { ...task, completed: !task.completed } : task
      )
    );
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter((task) => task.id !== id));
  };

  const pendingCount = tasks.filter((task) => !task.completed).length;

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-6">
      <div className="max-w-md mx-auto">
        <div className="bg-white rounded-xl shadow-lg p-6">
          <h1 className="text-2xl font-bold text-gray-800 mb-6">Mis Tareas</h1>

          <div className="flex gap-2 mb-6">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="¿Qué hay que hacer?"
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
            <button
              onClick={addTask}
              className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg transition-colors flex items-center gap-2"
            >
              <Plus size={20} />
              Agregar
            </button>
          </div>

          <div className="space-y-2 mb-4">
            {tasks.length === 0 ? (
              <div className="text-center py-8">
                <p className="text-gray-400 text-sm">No hay tareas</p>
              </div>
            ) : (
              <>
                {tasks.map((task) => (
                  <TaskItem
                    key={task.id}
                    task={task}
                    onToggle={toggleTask}
                    onDelete={deleteTask}
                  />
                ))}
              </>
            )}
          </div>

          {tasks.length > 0 && (
            <div className="text-center text-sm text-gray-600 border-t pt-4">
              {pendingCount === 0 ? (
                <p className="font-semibold text-green-600">¡Todas completadas!</p>
              ) : (
                <p>
                  <span className="font-semibold">{pendingCount}</span>{' '}
                  {pendingCount === 1 ? 'tarea pendiente' : 'tareas pendientes'}
                </p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

