import React, { useState, useMemo } from 'react';

type User = {
  id: number;
  name: string;
  email: string;
};

const INITIAL_USERS: User[] = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com' },
  { id: 3, name: 'Charlie Brown', email: 'charlie@example.com' },
  { id: 4, name: 'Diana Prince', email: 'diana@example.com' },
];

export default function App() {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredUsers = useMemo(() => {
    return INITIAL_USERS.filter(user =>
      user.name.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [searchTerm]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-800 mb-8">User Directory</h1>

        <div className="mb-8">
          <input
            type="text"
            placeholder="Search by name..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full px-4 py-3 rounded-lg border-2 border-indigo-300 focus:outline-none focus:border-indigo-600 text-gray-700 placeholder-gray-500 shadow-md transition-colors"
          />
        </div>

        <div className="mb-6 text-lg font-semibold text-gray-700">
          Results: <span className="text-indigo-600">{filteredUsers.length}</span>
        </div>

        <div className="grid grid-cols-1 gap-4">
          {filteredUsers.length > 0 ? (
            filteredUsers.map(user => (
              <div
                key={user.id}
                className="bg-white rounded-lg shadow-lg p-6 hover:shadow-xl transition-shadow border-l-4 border-indigo-600"
              >
                <h2 className="text-xl font-bold text-gray-800 mb-2">{user.name}</h2>
                <p className="text-gray-600 flex items-center gap-2">
                  <span className="text-indigo-600">✉</span>
                  {user.email}
                </p>
              </div>
            ))
          ) : (
            <div className="text-center py-12">
              <p className="text-gray-500 text-lg">No users found matching "{searchTerm}"</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

