                >
                  Agregar
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* Carrito */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-lg shadow-md p-6 sticky top-8">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Carrito</h2>

            {cart.length === 0 ? (
              <p className="text-gray-600 text-center py-8">
                El carrito está vacío
              </p>
            ) : (
              <>
                <div className="space-y-4 mb-6 max-h-80 overflow-y-auto">
                  {cart.map(item => (
                    <div
                      key={item.id}
                      className="border-b border-gray-200 pb-4 last:border-b-0"
                    >
                      <h3 className="font-semibold text-gray-800 mb-2">
                        {item.name}
                      </h3>
                      <p className="text-sm text-gray-600 mb-2">
                        ${item.price.toFixed(2)} c/u
                      </p>
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <button
                            onClick={() =>
                              updateQuantity(item.id, item.quantity - 1)
                            }
                            className="bg-red-500 hover:bg-red-600 text-white font-bold w-8 h-8 rounded transition-colors"
                          >
                            −
                          </button>
                          <span className="w-8 text-center font-semibold">
                            {item.quantity}
                          </span>
                          <button
                            onClick={() =>
                              updateQuantity(item.id, item.quantity + 1)
                            }
                            className="bg-green-500 hover:bg-green-600 text-white font-bold w-8 h-8 rounded transition-colors"
                          >
                            +
                          </button>
                        </div>
                        <p className="font-bold text-gray-800">
                          ${(item.price * item.quantity).toFixed(2)}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="border-t-2 border-gray-300 pt-4">
                  <div className="flex justify-between items-center">
                    <span className="text-lg font-bold text-gray-800">Total:</span>
                    <span className="text-2xl font-bold text-blue-600">
                      ${total.toFixed(2)}
                    </span>
