import * as http from 'node:http';
import { randomUUID } from 'node:crypto';

interface User {
  id: string;
  name: string;
  email: string;
}

const users: Map<string, User> = new Map();

const port = parseInt(process.env.PORT || '3000', 10);

function parseBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
    });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (err) {
        reject(err);
      }
    });
    req.on('error', reject);
  });
}

function sendJson(res: http.ServerResponse, statusCode: number, data: any) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

const server = http.createServer(async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url || '', `http://${req.headers.host}`);
  const pathname = url.pathname;

  if (pathname === '/api/users' && req.method === 'GET') {
    const userList = Array.from(users.values());
    sendJson(res, 200, userList);
    return;
  }

  if (pathname === '/api/users' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const { name, email } = body;

      if (!name || !email) {
        sendJson(res, 400, { message: 'Nombre y email son requeridos' });
        return;
      }

      if (typeof email !== 'string' || !email.includes('@')) {
        sendJson(res, 400, { message: 'Email inválido' });
        return;
      }

      const id = randomUUID();
      const user: User = { id, name, email };
      users.set(id, user);

      sendJson(res, 201, user);
      return;
    } catch (err) {
      sendJson(res, 400, { message: 'Error procesando la solicitud' });
      return;
    }
  }

  const deleteMatch = pathname.match(/^\/api\/users\/(.+)$/);
  if (deleteMatch && req.method === 'DELETE') {
    const id = deleteMatch[1];
    if (users.has(id)) {
      users.delete(id);
      sendJson(res, 200, { message: 'Usuario eliminado' });
      return;
    } else {
      sendJson(res, 404, { message: 'Usuario no encontrado' });
      return;
    }
  }

  sendJson(res, 404, { message: 'Ruta no encontrada' });
});

server.listen(port, () => {
  console.log(`Servidor escuchando en puerto ${port}`);
});

import { createServer } from 'node:http';

interface User {
	id: string;
	nombre: string;
	email: string;
}

const users: Map<string, User> = new Map();
let nextId = 1;

const server = createServer((req, res) => {
	res.setHeader('Access-Control-Allow-Origin', '*');
	res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
	res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

	if (req.method === 'OPTIONS') {
		res.writeHead(200);
		res.end();
		return;
	}

	const url = new URL(req.url || '', `http://${req.headers.host}`);

	// GET /api/users
	if (req.method === 'GET' && url.pathname === '/api/users') {
		res.writeHead(200, { 'Content-Type': 'application/json' });
		res.end(JSON.stringify(Array.from(users.values())));
		return;
	}

	// POST /api/users
	if (req.method === 'POST' && url.pathname === '/api/users') {
		let body = '';
		req.on('data', (chunk) => {
			body += chunk.toString();
		});
		req.on('end', () => {
			try {
				const { nombre, email } = JSON.parse(body);
				const id = String(nextId++);
				const newUser: User = { id, nombre, email };
				users.set(id, newUser);
				res.writeHead(201, { 'Content-Type': 'application/json' });
				res.end(JSON.stringify(newUser));
			} catch {
				res.writeHead(400, { 'Content-Type': 'application/json' });
				res.end(JSON.stringify({ error: 'Invalid request' }));
			}
		});
		return;
	}

	// DELETE /api/users/:id
	if (req.method === 'DELETE' && url.pathname.startsWith('/api/users/')) {
		const id = url.pathname.split('/').pop();
		if (id && users.has(id)) {
			users.delete(id);
			res.writeHead(200, { 'Content-Type': 'application/json' });
			res.end(JSON.stringify({ success: true }));
		} else {
			res.writeHead(404, { 'Content-Type': 'application/json' });
			res.end(JSON.stringify({ error: 'User not found' }));
		}
		return;
	}

	res.writeHead(404, { 'Content-Type': 'application/json' });
	res.end(JSON.stringify({ error: 'Not found' }));
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
	console.log(`Server running on port ${port}`);
});

