import { createServer } from 'node:http';
import { URL } from 'node:url';

interface Item {
	id: string;
	name: string;
	purchased: boolean;
}

const items: Map<string, Item> = new Map();
let nextId = 1;

function generateId(): string {
	return `item-${nextId++}`;
}

function parseBody(req: any): Promise<any> {
	return new Promise((resolve, reject) => {
		let data = '';
		req.on('data', (chunk: string) => {
			data += chunk;
		});
		req.on('end', () => {
			try {
				resolve(data ? JSON.parse(data) : {});
			} catch (error) {
				reject(error);
			}
		});
	});
}

const server = createServer(async (req, res) => {
	res.setHeader('Content-Type', 'application/json');
	res.setHeader('Access-Control-Allow-Origin', '*');
	res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
	res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

	if (req.method === 'OPTIONS') {
		res.writeHead(200);
		res.end();
		return;
	}

	const url = new URL(req.url || '', `http://${req.headers.host}`);
	const pathname = url.pathname;

	// GET /api/items
	if (pathname === '/api/items' && req.method === 'GET') {
		const itemList = Array.from(items.values());
		res.writeHead(200);
		res.end(JSON.stringify(itemList));
		return;
	}

	// POST /api/items
	if (pathname === '/api/items' && req.method === 'POST') {
		try {
			const body = await parseBody(req);
			const newItem: Item = {
				id: generateId(),
				name: body.name || '',
				purchased: false
			};
			items.set(newItem.id, newItem);
			res.writeHead(201);
			res.end(JSON.stringify(newItem));
		} catch (error) {
			res.writeHead(400);
			res.end(JSON.stringify({ error: 'Invalid request' }));
		}
		return;
	}

	// PATCH /api/items/:id
	if (pathname.match(/^\/api\/items\/[^/]+$/) && req.method === 'PATCH') {
		const id = pathname.split('/').pop();
		try {
			const body = await parseBody(req);
			const item = items.get(id!);
			if (!item) {
				res.writeHead(404);
				res.end(JSON.stringify({ error: 'Item not found' }));
				return;
			}
			item.purchased = body.purchased ?? item.purchased;
			res.writeHead(200);
			res.end(JSON.stringify(item));
		} catch (error) {
			res.writeHead(400);
			res.end(JSON.stringify({ error: 'Invalid request' }));
		}
		return;
	}

	// DELETE /api/items/:id
	if (pathname.match(/^\/api\/items\/[^/]+$/) && req.method === 'DELETE') {
		const id = pathname.split('/').pop();
		const existed = items.delete(id!);
		if (!existed) {
			res.writeHead(404);
			res.end(JSON.stringify({ error: 'Item not found' }));
			return;
		}
		res.writeHead(204);
		res.end();
		return;
	}

	// 404
	res.writeHead(404);
	res.end(JSON.stringify({ error: 'Not found' }));
});

const port = process.env.PORT || 3000;
server.listen(port, () => {
	console.log(`Server listening on port ${port}`);
});

